for k in [-1,0,1,2,3]:
    for m in [0,1,2]:
        cols.append(P**k * t**m); names.append(f'P^{k} t^{m}')
A=np.column_stack(cols)
c,_,_,_=np.linalg.lstsq(A,dP_dt,rcond=None)
